SELECT id, province, city, district_county AS districtCounty, hospital_name AS hospitalName, hospital_level AS hospitalLevel FROM hospital WHERE id IN
#{id}
ORDER BY id

SELECT id, province, city, district_county AS districtCounty, hospital_name AS hospitalName, hospital_level AS hospitalLevel FROM hospital WHERE city = #{city}
AND hospital_level = #{hospitalLevel}
ORDER BY hospital_name
